schemaSql:
CREATE TABLE IF NOT EXISTS productivity_lists(id TEXT PRIMARY KEY,title TEXT NOT NULL,owner_id TEXT NOT NULL,is_shared INTEGER NOT NULL CHECK(is_shared IN(0,1)));
CREATE TABLE IF NOT EXISTS productivity_sections(id TEXT PRIMARY KEY,list_id TEXT NOT NULL REFERENCES productivity_lists(id),title TEXT NOT NULL,UNIQUE(id,list_id));
CREATE TABLE IF NOT EXISTS productivity_tags(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS productivity_tasks(
 id TEXT PRIMARY KEY,list_id TEXT NOT NULL REFERENCES productivity_lists(id),section_id TEXT,parent_id TEXT REFERENCES productivity_tasks(id) DEFERRABLE INITIALLY DEFERRED,
 title TEXT NOT NULL,body TEXT NOT NULL,lifecycle TEXT NOT NULL CHECK(lifecycle IN('todo','in_progress','completed','wont_do')),priority TEXT NOT NULL CHECK(priority IN('high','medium','low','none')),
 due_kind TEXT NOT NULL CHECK(due_kind IN('none','all_day','timed')),due_date TEXT,due_instant TEXT,due_timezone TEXT,
 scheduled_start TEXT,scheduled_end TEXT,creator_id TEXT NOT NULL,assignee_id TEXT,is_shared INTEGER NOT NULL CHECK(is_shared IN(0,1)),blocked INTEGER NOT NULL CHECK(blocked IN(0,1)),blocked_reason TEXT,
 pending_approval INTEGER NOT NULL CHECK(pending_approval IN(0,1)),reward_points INTEGER NOT NULL CHECK(reward_points>=0),revision INTEGER NOT NULL CHECK(revision>=0),deleted_at TEXT,rank INTEGER NOT NULL,legacy_json TEXT NOT NULL,
 FOREIGN KEY(section_id,list_id) REFERENCES productivity_sections(id,list_id) DEFERRABLE INITIALLY DEFERRED,
 CHECK((due_kind='none' AND due_date IS NULL AND due_instant IS NULL AND due_timezone IS NULL) OR (due_kind='all_day' AND due_date IS NOT NULL AND due_instant IS NULL AND due_timezone IS NOT NULL) OR (due_kind='timed' AND due_date IS NULL AND due_instant IS NOT NULL AND due_timezone IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS productivity_tasks_list_rank ON productivity_tasks(list_id,rank,id);
CREATE INDEX IF NOT EXISTS productivity_tasks_actor ON productivity_tasks(assignee_id,lifecycle,id);
CREATE INDEX IF NOT EXISTS productivity_tasks_due ON productivity_tasks(due_kind,due_date,due_instant,id);
CREATE TABLE IF NOT EXISTS productivity_task_tags(task_id TEXT NOT NULL REFERENCES productivity_tasks(id) ON DELETE CASCADE,tag_id TEXT NOT NULL REFERENCES productivity_tags(id),PRIMARY KEY(task_id,tag_id));
CREATE TABLE IF NOT EXISTS productivity_list_grants(list_id TEXT NOT NULL REFERENCES productivity_lists(id),user_id TEXT NOT NULL,permission TEXT NOT NULL CHECK(permission IN('read','write','manage')),PRIMARY KEY(list_id,user_id));
CREATE TABLE IF NOT EXISTS productivity_occurrences(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES productivity_tasks(id),series_id TEXT NOT NULL,occurrence_key TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(ordinal>=0),payload_json TEXT NOT NULL,UNIQUE(series_id,occurrence_key));
CREATE TABLE IF NOT EXISTS productivity_matrix_pins(view_id TEXT NOT NULL,task_id TEXT NOT NULL REFERENCES productivity_tasks(id) ON DELETE CASCADE,quadrant TEXT NOT NULL CHECK(quadrant IN('q1','q2','q3','q4')),PRIMARY KEY(view_id,task_id));

CREATE TABLE productivity_catalog_revisions(
 entity_kind TEXT NOT NULL CHECK(entity_kind IN('list','section','tag')),entity_id TEXT NOT NULL,
 revision INTEGER NOT NULL CHECK(revision>=1),archived_at TEXT,PRIMARY KEY(entity_kind,entity_id)
);
CREATE TABLE productivity_check_items(
 id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES productivity_tasks(id) ON DELETE CASCADE,
 text TEXT NOT NULL,is_done INTEGER NOT NULL CHECK(is_done IN(0,1)),rank INTEGER NOT NULL,
 UNIQUE(task_id,rank)
);
CREATE INDEX productivity_tasks_parent ON productivity_tasks(parent_id,deleted_at);
CREATE INDEX productivity_check_items_task ON productivity_check_items(task_id,rank,id);
CREATE TABLE productivity_tag_owners(
 tag_id TEXT PRIMARY KEY REFERENCES productivity_tags(id) ON DELETE CASCADE,
 user_id TEXT NOT NULL
);
CREATE INDEX productivity_tag_owners_user ON productivity_tag_owners(user_id,tag_id);
CREATE TABLE productivity_task_pins(
 user_id TEXT NOT NULL,
 task_id TEXT NOT NULL REFERENCES productivity_tasks(id) ON DELETE CASCADE,
 is_pinned INTEGER NOT NULL CHECK(is_pinned IN(0,1)),
 revision INTEGER NOT NULL CHECK(revision>=1),
 PRIMARY KEY(user_id,task_id)
);
CREATE INDEX productivity_task_pins_task ON productivity_task_pins(task_id,user_id);

CREATE TABLE productivity_views(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,title TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>=1),filter_json TEXT NOT NULL CHECK(json_valid(filter_json)),kind TEXT NOT NULL CHECK(kind IN('list','matrix','kanban','calendar','timeline')),config_json TEXT NOT NULL CHECK(json_valid(config_json)));
CREATE INDEX productivity_views_owner ON productivity_views(owner_id,id);
CREATE TABLE productivity_search_documents(task_id TEXT PRIMARY KEY REFERENCES productivity_tasks(id) ON DELETE CASCADE,content TEXT NOT NULL);
CREATE TABLE productivity_search_grams(task_id TEXT NOT NULL REFERENCES productivity_search_documents(task_id) ON DELETE CASCADE,gram TEXT NOT NULL,PRIMARY KEY(task_id,gram));
CREATE INDEX productivity_search_grams_lookup ON productivity_search_grams(gram,task_id);

CREATE TABLE productivity_matrix_overrides(
 view_id TEXT NOT NULL REFERENCES productivity_views(id) ON DELETE CASCADE,task_id TEXT NOT NULL REFERENCES productivity_tasks(id) ON DELETE CASCADE,
 quadrant TEXT NOT NULL CHECK(quadrant IN('q1','q2','q3','q4')),
 view_revision INTEGER NOT NULL CHECK(typeof(view_revision)='integer' AND view_revision>=1),revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1),expires_at TEXT,
 PRIMARY KEY(view_id,task_id)
);
CREATE INDEX productivity_matrix_overrides_expiry ON productivity_matrix_overrides(expires_at,view_id,task_id);

CREATE TABLE productivity_boards(
 id TEXT PRIMARY KEY NOT NULL CHECK(length(trim(id)) BETWEEN 1 AND 256),
 list_id TEXT NOT NULL REFERENCES productivity_lists(id),
 mode TEXT NOT NULL CHECK(mode IN('sections','workflow')),
 revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision BETWEEN 1 AND 9007199254740991),
 UNIQUE(list_id,mode),UNIQUE(id,list_id)
);
CREATE TABLE productivity_board_columns(
 board_id TEXT NOT NULL,id TEXT NOT NULL CHECK(length(trim(id)) BETWEEN 1 AND 256),list_id TEXT NOT NULL,
 column_key TEXT NOT NULL CHECK(length(trim(column_key)) BETWEEN 1 AND 264),section_id TEXT,
 rank INTEGER NOT NULL CHECK(typeof(rank)='integer' AND rank BETWEEN 0 AND 9007199254740991),
 wip_limit INTEGER,wip_policy TEXT NOT NULL CHECK(wip_policy IN('off','soft','hard')),archived_at TEXT,
 revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision BETWEEN 1 AND 9007199254740991),
 PRIMARY KEY(board_id,id),UNIQUE(board_id,column_key),UNIQUE(board_id,id,list_id),
 FOREIGN KEY(board_id,list_id) REFERENCES productivity_boards(id,list_id),
 FOREIGN KEY(section_id,list_id) REFERENCES productivity_sections(id,list_id),
 CHECK((wip_policy='off' AND wip_limit IS NULL) OR (wip_policy IN('soft','hard') AND typeof(wip_limit)='integer' AND wip_limit BETWEEN 1 AND 9007199254740991))
);
CREATE UNIQUE INDEX productivity_tasks_board_identity ON productivity_tasks(id,list_id);
CREATE TABLE productivity_board_positions(
 board_id TEXT NOT NULL,task_id TEXT NOT NULL,list_id TEXT NOT NULL,column_id TEXT NOT NULL,
 rank INTEGER NOT NULL CHECK(typeof(rank)='integer' AND rank BETWEEN 0 AND 9007199254740991),
 PRIMARY KEY(board_id,task_id),
 FOREIGN KEY(board_id,column_id,list_id) REFERENCES productivity_board_columns(board_id,id,list_id),
 FOREIGN KEY(task_id,list_id) REFERENCES productivity_tasks(id,list_id) ON DELETE CASCADE
);
CREATE INDEX productivity_board_positions_lane ON productivity_board_positions(board_id,column_id,rank,task_id);

CREATE TABLE productivity_series(
 id TEXT PRIMARY KEY,task_id TEXT NOT NULL UNIQUE REFERENCES productivity_tasks(id),
 revision INTEGER NOT NULL CHECK(revision>=1),policy_json TEXT NOT NULL,anchor_json TEXT NOT NULL,
 next_ordinal INTEGER NOT NULL CHECK(next_ordinal>=1),accepted_count INTEGER NOT NULL CHECK(accepted_count>=0),
 rotation_cursor INTEGER NOT NULL CHECK(rotation_cursor>=0),ended_at TEXT,
 created_at TEXT NOT NULL,updated_at TEXT NOT NULL
);
CREATE TABLE productivity_series_exceptions(
 series_id TEXT NOT NULL REFERENCES productivity_series(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),
 kind TEXT NOT NULL CHECK(kind IN('skip','due')),due_json TEXT,
 revision INTEGER NOT NULL CHECK(revision>=1),PRIMARY KEY(series_id,ordinal),
 CHECK((kind='skip' AND due_json IS NULL) OR (kind='due' AND due_json IS NOT NULL))
);

CREATE TABLE productivity_series_occurrences(
 series_id TEXT NOT NULL REFERENCES productivity_series(id),
 ordinal INTEGER NOT NULL CHECK(ordinal>=0 AND ordinal<=100000),
 task_id TEXT NOT NULL UNIQUE REFERENCES productivity_tasks(id),
 state TEXT NOT NULL CHECK(state IN('open','accepted')),policy_json TEXT NOT NULL,due_json TEXT NOT NULL,
 created_at TEXT NOT NULL,accepted_at TEXT,accepted_revision INTEGER,
 PRIMARY KEY(series_id,ordinal),
 CHECK((state='open' AND ordinal>0 AND accepted_at IS NULL AND accepted_revision IS NULL) OR
       (state='accepted' AND accepted_at IS NOT NULL AND accepted_revision IS NOT NULL AND accepted_revision>=1))
);

CREATE TABLE productivity_occurrence_skips(
 series_id TEXT NOT NULL REFERENCES productivity_series(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0 AND ordinal<=100000),
 task_id TEXT NOT NULL UNIQUE REFERENCES productivity_tasks(id),skipped_at TEXT NOT NULL,
 skipped_by_id TEXT NOT NULL REFERENCES users(id),task_revision INTEGER NOT NULL CHECK(task_revision>=1),
 PRIMARY KEY(series_id,ordinal)
);

CREATE TABLE productivity_legacy_cutovers(
 legacy_root_task_id TEXT NOT NULL PRIMARY KEY REFERENCES productivity_tasks(id),
 series_id TEXT NOT NULL UNIQUE REFERENCES productivity_series(id),
 selected_task_id TEXT NOT NULL UNIQUE REFERENCES productivity_tasks(id),
 actor_id TEXT NOT NULL REFERENCES users(id),
 source_json TEXT NOT NULL CHECK(json_valid(source_json)),created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS wallet_currencies(code TEXT PRIMARY KEY,exponent INTEGER NOT NULL CHECK(exponent BETWEEN 0 AND 8));
INSERT OR IGNORE INTO wallet_currencies VALUES('VND',0),('USD',2);
CREATE TABLE IF NOT EXISTS wallet_accounts(
 id TEXT PRIMARY KEY,name TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN('cash','bank','savings','credit','e_wallet','investment','asset','liability')),
 currency TEXT NOT NULL REFERENCES wallet_currencies(code),owner_user_id TEXT NOT NULL,access_mode TEXT NOT NULL CHECK(access_mode IN('shared','private')),
 opening_minor INTEGER NOT NULL CHECK(typeof(opening_minor)='integer'),opening_date TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>=1),archived_at TEXT);
CREATE TABLE IF NOT EXISTS wallet_account_grants(account_id TEXT NOT NULL REFERENCES wallet_accounts(id),user_id TEXT NOT NULL,permission TEXT NOT NULL CHECK(permission IN('read','contribute','manage')),PRIMARY KEY(account_id,user_id));
CREATE TABLE IF NOT EXISTS wallet_categories(id TEXT PRIMARY KEY,parent_id TEXT REFERENCES wallet_categories(id) DEFERRABLE INITIALLY DEFERRED,name TEXT NOT NULL,nature TEXT NOT NULL CHECK(nature IN('must','need','want','unspecified')),archived_at TEXT);
CREATE TABLE IF NOT EXISTS wallet_labels(id TEXT PRIMARY KEY,name TEXT NOT NULL,archived_at TEXT);
CREATE TABLE IF NOT EXISTS wallet_schedules(id TEXT PRIMARY KEY,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)));
CREATE TABLE IF NOT EXISTS wallet_occurrences(id TEXT PRIMARY KEY,schedule_id TEXT NOT NULL REFERENCES wallet_schedules(id),due_date TEXT NOT NULL,UNIQUE(schedule_id,due_date));
CREATE TABLE IF NOT EXISTS wallet_records(
 id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('income','expense','transfer','adjustment','trade')),effective_date TEXT NOT NULL,timezone TEXT NOT NULL,
 source TEXT NOT NULL CHECK(source IN('manual','import','schedule','legacy')),external_key TEXT,note TEXT NOT NULL,
 settlement_status TEXT NOT NULL CHECK(settlement_status IN('uncleared','cleared','reconciled','voided')),creator_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>=1),
 category_id TEXT REFERENCES wallet_categories(id),occurrence_id TEXT UNIQUE REFERENCES wallet_occurrences(id),UNIQUE(id,effective_date));
CREATE UNIQUE INDEX IF NOT EXISTS wallet_record_external_key ON wallet_records(source,external_key) WHERE external_key IS NOT NULL;
CREATE TABLE IF NOT EXISTS wallet_postings(record_id TEXT NOT NULL,account_id TEXT NOT NULL REFERENCES wallet_accounts(id),effective_date TEXT NOT NULL,delta_minor INTEGER NOT NULL CHECK(typeof(delta_minor)='integer'),PRIMARY KEY(record_id,account_id),FOREIGN KEY(record_id,effective_date) REFERENCES wallet_records(id,effective_date));
CREATE INDEX IF NOT EXISTS wallet_posting_account_date ON wallet_postings(account_id,effective_date,record_id);
CREATE TABLE IF NOT EXISTS wallet_record_labels(record_id TEXT NOT NULL REFERENCES wallet_records(id),label_id TEXT NOT NULL REFERENCES wallet_labels(id),PRIMARY KEY(record_id,label_id));
CREATE TABLE IF NOT EXISTS wallet_allocations(record_id TEXT NOT NULL REFERENCES wallet_records(id),category_id TEXT NOT NULL REFERENCES wallet_categories(id),amount_minor INTEGER NOT NULL CHECK(typeof(amount_minor)='integer' AND amount_minor>=0),PRIMARY KEY(record_id,category_id));
CREATE TABLE IF NOT EXISTS wallet_audit(id TEXT PRIMARY KEY,record_id TEXT REFERENCES wallet_records(id),actor_id TEXT NOT NULL,action TEXT NOT NULL);
